INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (368337, 15702, 'Navbharat Times', 'hi', 'दक्षिण कोरिया ने ईरान में मदद नहीं की तो हम क्यों करेंगे? डोनाल्ड ट्रंप दोस्त से ले रहे ''बदला'', बड़ा ऐलान', 'https://news.google.?oc=5', 'दक्षिण कोरिया ने ईरान में मदद नहीं की तो हम क्यों करेंगे? डोनाल्ड ट्रंप दोस्त से ले रहे ''बदला'', बड़ा ऐलान Navbharat Times', '', '2026-08-18T03:08:37+00:00', '2026-08-18T05:45:12.211952'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371765, 15702, 'Aaj Tak', 'hi', 'ईरान का अमेरिकी सैनिकों को मारने-पकड़ने पर इनाम का ऐलान, भड़के ट्रंप', 'https://www.aajtak.in/world/video/trump-furious-over-announcement-of-commander-in-chief-amir-hatam-bounties-for-killing-and-capturing-us-troops-vdoj-2624772-2026-08-18', 'ईरानी आर्मी ने अमेरिकी सैनिकों को मारने और पकड़ने पर इनाम का ऐलान किया है. ये एलान किया है ईरान के कमांडर-इन चीफ अमिर हातमी ने. उन्होंने कहा है कि जो भी अमेरिकी सैनिक को मारेगा या पकड़कर हमारी सेना के हवाले करेगा, उसे 30,000 डॉलर के बराबर का तोहफा दिया जाएगा. ईरान की सरकारी समाचार एजेंसी के मुताबिक आर्मी कमांडर ने कहा है कि अमेरिकी सैनिकों पर इनाम घोषित करने की ये योजना वित्तीय सहायता के लिए आए ढेर सारे अनुरोधों के बाद तैयार की गई है.', '', '2026-08-18T09:06:02+00:00', '2026-08-18T09:13:27.008934'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
