INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (364731, 15710, 'Patrika', 'hi', 'पटना में 18 अगस्त से छात्रों का महाआंदोलन , दिलीप कुमार बोले - TRE 4 का विज्ञापन निकालें या शिक्षा मंत्री दें इस्तीफा | Dilip Kumar Bihar Student Protest Bpsc Bssc Gardnibagh August 18', 'https://www.patrika.com/patna-news/dilip-kumar-bihar-student-protest-bpsc-bssc-gardnibagh-august-18-20839830', '', 'https://cms.patrika.com/wp-content/uploads/2026/06/bihar-student-protest.webp', '20260817', '2026-08-17T22:43:09.558467'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (368348, 15710, 'Aaj Tak', 'hi', 'घेर लेंगे व‍िधानसभा! अब बि‍हार में TRE-4 पर छात्र आंदोलन शुरू', 'https://www.aajtak.in/education/news/story/bihar-tre-4-student-protest-recruitment-advertisement-demands-edmm-dskc-2624510-2026-08-18', 'दिल्ली और रांची के बाद अब बिहार में भी छात्र आंदोलन ने जोर पकड़ लिया है. मंगलवार से पटना के गर्दनीबाग में TRE-4 शिक्षक भर्ती समेत लंबित परीक्षाओं के अभ्यर्थी अनिश्चितकालीन आमरण अनशन पर बैठ गए हैं. छात्र नेता दिलीप कुमार के नेतृत्व में युवा सड़क पर हैं. मांग साफ है, TRE-4 का विज्ञापन तुरंत जारी हो, नहीं तो शिक्षा मंत्री इस्तीफा दें. पांच दिन का अल्टीमेटम देकर विधानसभा घेराव की चेतावनी भी दी गई है.', '', '2026-08-18T05:07:45+00:00', '2026-08-18T05:45:15.063647'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (369187, 15710, 'Amar Ujala', 'hi', 'BPSC TRE 4: शिक्षक अभ्यर्थियों के लिए बड़ी खुशखबरी, बीपीएससी आज जारी करेगा टीआरई 4 का विज्ञापन, पढ़िए पूरी खबर', 'https://www.amarujala.com/bihar/bpsc-tre-4-news-bpsc-tre-4-notification-teacher-recruitment-exam-bihar-exam-news-2026-08-18', 'लंबे समय से शिक्षक भर्ती परीक्षा का इंतजार कर रहे अभ्यर्थियों के लिए खुशखबरी है। आज बिहार लोक सेवा आयोग चौथे चरण की शिक्षक भर्ती परीक्षा का विज्ञापन जारी कर देगा। आइये जानते हैं पूरा मामला...', '', '2026-08-18T05:59:36+00:00', '2026-08-18T06:40:02.037907'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (369211, 15710, 'Aaj Tak', 'hi', 'क्या बिहार मे आंदोलन रोकने के ल‍िए आज ही आएगा TRE-4 नोटिफिकेशन?', 'https://www.aajtak.in/education/news/story/tre-4-teacher-recruitment-bihar-bpsc-advertisement-student-protest-edmm-rpti-2624568-2026-08-18', 'पटना के गर्दनीबाग में मंगलवार सुबह से TRE-4 शिक्षक भर्ती के अभ्यर्थी आमरण अनशन पर बैठ गए. लेकिन आंदोलन शुरू होते ही बड़ी अपडेट सामने आई. सूत्रों का दावा है कि BPSC आज शाम तक TRE-4 का विज्ञापन जारी कर सकता है. माना जा रहा है कि बिहार सरकार दिल्ली और झारखंड जैसे बड़े छात्र आंदोलन से बचना चाहती है.', '', '2026-08-18T06:32:11+00:00', '2026-08-18T06:40:07.947407'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
