INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (369824, 15713, 'LiveLaw', 'en', 'Supreme Court Dismisses Plea To Abolish Hanging As Method To Execute Death Penalty , Says Union Can Explore Alternatives', 'https://www.livelaw.in/top-stories/supreme-court-dismisses-plea-to-abolish-hanging-as-method-to-execute-death-penalty-says-union-free-to-explore-alternatives-546213', '', 'https://www.livelaw.in/h-upload/2025/10/08/624747-750x450622433-750x450399744-timing-of-sentencing-in-death-penalty-cases-supreme-court-to-hear-the-matter-in-january-2024-1.jpg', '20260818', '2026-08-18T06:46:22.317572'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370020, 15713, 'The Times of India', 'en', 'Death penalty by lethal injection, shooting or electrocution? SC rejects plea', 'https://timesofindia.indiatimes.com/legal/news/death-penalty-by-lethal-injection-shooting-or-electrocution-sc-rejects-plea/articleshow/133313839.cms', 'The Supreme Court declined to abolish hanging as an execution method. New scientific evidence could prompt future reconsideration of this decision. The court permitted the Centre to form an expert panel. This panel will examine alternative execution methods for reduced pain. Hanging remains the current method while reviews are pending.', 'https://static.toiimg.com/photo/msid-133314083,imgsize-101823.cms', '2026-08-18T06:44:02+00:00', '2026-08-18T07:26:42.716144'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
